-- Fill in the BellaBot product page (Admin -> Products -> pudu-bella) with
-- the full-screen design: header cut-out, four key figures, six photo
-- sections, a calling section, the spec table and four FAQs.
--
-- Facts come from Pudu's BellaBot page (pudurobotics.com/en/products/bellabot).
-- Photos are Pudu's studio shots with the Pudu marks painted out
-- (public/models/pudu/bellabot/); the header is the logo-free cut-out on S3.
-- The Thai text is a DRAFT for the Thai team.
--
-- Renames the product to "BellaBot" and sets its photo, texts and page.
-- Leaves alone: price, visible, conditions (how it is sold), the recommender
-- facts (fit) and the order. Safe to run before the new code is live: the
-- row stays hidden until Visible is ticked in Admin. Safe to re-run.
--
-- Run in Supabase: SQL Editor -> New query -> paste -> Run. Nothing to edit.

begin;

update public.products set
  name = 'BellaBot',
  brand = 'Pudu',
  category = 'delivery-robots',
  image_url = 'https://d5hk9n8my7l32.cloudfront.net/Pudu/BellaBot/BellaBot-cutout.webp',
  tagline = '{"en":"A cat-faced delivery robot that carries four trays to the table and charms guests on the way.","th":"หุ่นยนต์เสิร์ฟอาหารหน้าแมว ส่งอาหาร 4 ถาดถึงโต๊ะ พร้อมสร้างรอยยิ้มให้ลูกค้าระหว่างทาง"}'::jsonb,
  description = '{"en":"Pudu BellaBot delivery robot in Thailand: 4 trays and up to 40 kg per trip, 13 h battery life, laser and camera navigation, 3D obstacle avoidance. Get a quote from FindMyRobo.","th":"หุ่นยนต์เสิร์ฟอาหาร Pudu BellaBot ในประเทศไทย 4 ถาด รับน้ำหนักได้ถึง 40 กก. ต่อรอบ แบตเตอรี่ใช้งานได้ 13 ชม. นำทางด้วยเลเซอร์และกล้อง หลบสิ่งกีดขวางแบบ 3 มิติ ขอใบเสนอราคาจาก FindMyRobo"}'::jsonb,
  features = '{"en":["Max load: 40 kg (4 trays)","Battery life: 13 h (no load)","Speed: 0.5–1.2 m/s","Obstacle sensing: 3 RGBD cameras + LiDAR"],"th":["รับน้ำหนักสูงสุด: 40 กก. (4 ถาด)","แบตเตอรี่ใช้งานได้: 13 ชม. (ไม่มีน้ำหนักบรรทุก)","ความเร็ว: 0.5–1.2 ม./วินาที","ตรวจจับสิ่งกีดขวาง: กล้อง RGBD 3 ตัว + LiDAR"]}'::jsonb,
  page = '{"showcase":{"eyebrow":{"en":"Pudu · Delivery robot for restaurants and retail","th":"Pudu · หุ่นยนต์เสิร์ฟอาหารสำหรับร้านอาหารและร้านค้า"},"heroImage":"https://d5hk9n8my7l32.cloudfront.net/Pudu/BellaBot/BellaBot-cutout.webp","figures":[{"value":"4","label":{"en":"Trays","th":"ถาด"}},{"value":"40 kg","label":{"en":"Max load, 10 kg per tray","th":"รับน้ำหนักสูงสุด ถาดละ 10 กก."}},{"value":"13 h","label":{"en":"Battery life, no load","th":"แบตเตอรี่ ไม่มีน้ำหนักบรรทุก"}},{"value":"0.5–1.2 m/s","label":{"en":"Speed, adjustable","th":"ความเร็ว ปรับได้"}}]},"blocks":[{"type":"feature","eyebrow":{"en":"Navigation","th":"การนำทาง"},"heading":{"en":"Finds its own way.","th":"หาทางไปเองได้"},"body":{"en":"BellaBot navigates by laser (LiDAR) or by camera (visual SLAM), so it suits more kinds of venue. Laser positioning needs no markers and works under any ceiling height; marker positioning works with ceilings up to 8 m.","th":"BellaBot นำทางได้ทั้งด้วยเลเซอร์ (LiDAR) และด้วยกล้อง (Visual SLAM) จึงใช้งานได้ในสถานที่หลากหลายกว่า การระบุตำแหน่งด้วยเลเซอร์ไม่ต้องติดมาร์กเกอร์และไม่จำกัดความสูงเพดาน ส่วนแบบใช้มาร์กเกอร์รองรับเพดานสูงได้ถึง 8 เมตร"},"image":"/models/pudu/bellabot/navigation.webp"},{"type":"feature","eyebrow":{"en":"Safety","th":"ความปลอดภัย"},"heading":{"en":"Sees obstacles in 3D.","th":"มองเห็นสิ่งกีดขวางแบบ 3 มิติ"},"body":{"en":"Three RGBD depth cameras work with the LiDAR to spot obstacles from any angle, including low ones and ones that hang over its path. It stops in as little as 0.5 seconds, then moves on around them.","th":"กล้องวัดความลึก RGBD 3 ตัวทำงานร่วมกับ LiDAR ตรวจจับสิ่งกีดขวางได้จากทุกมุม ทั้งสิ่งที่อยู่ต่ำและสิ่งที่ยื่นลงมาขวางทาง หยุดได้เร็วสุดภายใน 0.5 วินาที แล้วเลี่ยงไปต่อ"},"image":"/models/pudu/bellabot/sensors.webp"},{"type":"feature","eyebrow":{"en":"Guests","th":"ลูกค้า"},"heading":{"en":"A cat people come back to see.","th":"แมวที่ลูกค้าอยากกลับมาเจออีก"},"body":{"en":"Dozens of original cat expressions on its face, voice greetings, lights that show what it is doing, and a response when it is touched. BellaBot is built to bring guests a little delight with every delivery.","th":"ใบหน้าแสดงอารมณ์แมวได้หลายสิบแบบ มีเสียงทักทาย ไฟบอกสถานะการทำงาน และตอบสนองเมื่อถูกสัมผัส BellaBot ถูกออกแบบมาเพื่อสร้างความประทับใจเล็ก ๆ ให้ลูกค้าในทุกการเสิร์ฟ"},"image":"/models/pudu/bellabot/guests.webp"},{"type":"feature","eyebrow":{"en":"Trays","th":"ถาด"},"heading":{"en":"Four trays, 40 kg a trip.","th":"4 ถาด 40 กก. ต่อรอบ"},"body":{"en":"Each 41 × 50 cm tray holds up to 10 kg. An infrared sensor watches the trays, and the trays come off quickly for cleaning.","th":"ถาดขนาด 41 × 50 ซม. รับน้ำหนักได้ถาดละ 10 กก. มีเซนเซอร์อินฟราเรดตรวจจับถาด และถอดถาดออกมาทำความสะอาดได้ง่าย"},"image":"/models/pudu/bellabot/trays.webp"},{"type":"feature","eyebrow":{"en":"Ride","th":"การเคลื่อนที่"},"heading":{"en":"Soup stays in the bowl.","th":"ซุปไม่หกจากชาม"},"body":{"en":"Automotive-grade independent suspension adjusts its damping to the floor, keeping the trays steady on the way to the table. It handles slopes of up to 5°.","th":"ระบบกันสะเทือนอิสระระดับยานยนต์ปรับความหน่วงตามสภาพพื้น ช่วยให้ถาดนิ่งตลอดทางไปถึงโต๊ะ และขึ้นทางลาดได้สูงสุด 5°"},"image":"/models/pudu/bellabot/suspension.webp"},{"type":"feature","eyebrow":{"en":"Battery","th":"แบตเตอรี่"},"heading":{"en":"Swap the battery, keep serving.","th":"เปลี่ยนแบตเตอรี่ แล้วเสิร์ฟต่อได้ทันที"},"body":{"en":"Up to 13 hours on a charge without a load, and 4.5 hours to recharge. The battery swaps out quickly, so BellaBot can keep working through long days.","th":"ใช้งานได้สูงสุด 13 ชั่วโมงต่อการชาร์จเมื่อไม่มีน้ำหนักบรรทุก ชาร์จเต็มใน 4.5 ชั่วโมง และเปลี่ยนแบตเตอรี่ได้รวดเร็ว BellaBot จึงทำงานต่อเนื่องได้ตลอดวันที่ยาวนาน"},"image":"/models/pudu/bellabot/battery.webp"},{"type":"feature","eyebrow":{"en":"Calling","th":"การเรียกใช้งาน"},"heading":{"en":"Call it from anywhere.","th":"เรียกใช้งานได้จากทุกที่"},"body":{"en":"Staff can call and manage BellaBot from the PUDU Link app, a push-button caller or a 4G watch. The app also shows each robot''s status and operating data. Calling devices are optional: ask us what is included.","th":"พนักงานเรียกและจัดการ BellaBot ได้ผ่านแอป PUDU Link ปุ่มกดเรียก หรือนาฬิกา 4G แอปยังแสดงสถานะและข้อมูลการทำงานของหุ่นยนต์แต่ละตัว อุปกรณ์เรียกเป็นตัวเลือกเสริม สอบถามเราได้ว่ามีอะไรรวมอยู่บ้าง"}}],"specGroups":[{"title":{"en":"Trays and load","th":"ถาดและน้ำหนักบรรทุก"},"rows":[{"label":{"en":"Trays","th":"จำนวนถาด"},"value":{"en":"4","th":"4 ถาด"}},{"label":{"en":"Max load","th":"รับน้ำหนักสูงสุด"},"value":{"en":"40 kg, 10 kg per tray","th":"40 กก. ถาดละ 10 กก."}},{"label":{"en":"Tray size","th":"ขนาดถาด"},"value":{"en":"41 × 50 cm","th":"41 × 50 ซม."}},{"label":{"en":"Tray heights, top to bottom","th":"ความสูงถาด จากบนลงล่าง"},"value":{"en":"23 / 20 / 20 / 18 cm","th":"23 / 20 / 20 / 18 ซม."}},{"label":{"en":"Tray sensor","th":"เซนเซอร์ถาด"},"value":{"en":"Infrared","th":"อินฟราเรด"}}]},{"title":{"en":"Battery","th":"แบตเตอรี่"},"rows":[{"label":{"en":"Battery life","th":"ระยะเวลาใช้งาน"},"value":{"en":"13 h, no load","th":"13 ชม. ไม่มีน้ำหนักบรรทุก"}},{"label":{"en":"Charging time","th":"เวลาชาร์จ"},"value":{"en":"4.5 h","th":"4.5 ชม."}},{"label":{"en":"Battery swap","th":"เปลี่ยนแบตเตอรี่"},"value":{"en":"Yes, quick swap","th":"ได้ เปลี่ยนได้รวดเร็ว"}}]},{"title":{"en":"Movement","th":"การเคลื่อนที่"},"rows":[{"label":{"en":"Speed","th":"ความเร็ว"},"value":{"en":"0.5–1.2 m/s, adjustable","th":"0.5–1.2 ม./วินาที ปรับได้"}},{"label":{"en":"Climbing angle","th":"ทางลาด"},"value":{"en":"Up to 5°","th":"สูงสุด 5°"}},{"label":{"en":"Suspension","th":"ระบบกันสะเทือน"},"value":{"en":"Automotive-grade independent suspension","th":"ระบบกันสะเทือนอิสระระดับยานยนต์"}}]},{"title":{"en":"Navigation and sensors","th":"การนำทางและเซนเซอร์"},"rows":[{"label":{"en":"Navigation","th":"การนำทาง"},"value":{"en":"LiDAR SLAM and visual SLAM","th":"LiDAR SLAM และ Visual SLAM"}},{"label":{"en":"Positioning","th":"การระบุตำแหน่ง"},"value":{"en":"Laser: no markers, any ceiling height. Markers: ceilings up to 8 m","th":"เลเซอร์: ไม่ต้องใช้มาร์กเกอร์ ไม่จำกัดความสูงเพดาน / มาร์กเกอร์: เพดานสูงไม่เกิน 8 ม."}},{"label":{"en":"Obstacle sensing","th":"การตรวจจับสิ่งกีดขวาง"},"value":{"en":"3 RGBD cameras + LiDAR","th":"กล้อง RGBD 3 ตัว + LiDAR"}},{"label":{"en":"Stopping response","th":"เวลาตอบสนองในการหยุด"},"value":{"en":"As short as 0.5 s","th":"เร็วสุด 0.5 วินาที"}}]},{"title":{"en":"Interaction and calling","th":"การโต้ตอบและการเรียกใช้งาน"},"rows":[{"label":{"en":"Interaction","th":"การโต้ตอบ"},"value":{"en":"Cat expressions, voice, status lights, touch response","th":"ใบหน้าแสดงอารมณ์แมว เสียง ไฟสถานะ ตอบสนองต่อการสัมผัส"}},{"label":{"en":"Calling","th":"การเรียกใช้งาน"},"value":{"en":"PUDU Link app, push-button caller, 4G watch (optional)","th":"แอป PUDU Link ปุ่มกดเรียก นาฬิกา 4G (ตัวเลือกเสริม)"}}]},{"title":{"en":"Size and weight","th":"ขนาดและน้ำหนัก"},"rows":[{"label":{"en":"Dimensions (L × W × H)","th":"ขนาด (ยาว × กว้าง × สูง)"},"value":{"en":"565 × 537 × 1,290 mm","th":"565 × 537 × 1,290 มม."}},{"label":{"en":"Weight","th":"น้ำหนัก"},"value":{"en":"55 kg","th":"55 กก."}},{"label":{"en":"Materials","th":"วัสดุ"},"value":{"en":"ABS and aircraft-grade aluminium alloy","th":"ABS และอะลูมิเนียมอัลลอยเกรดอากาศยาน"}}]}],"faqs":[{"question":{"en":"Do we need to put markers on the ceiling?","th":"ต้องติดมาร์กเกอร์บนเพดานหรือไม่"},"answer":{"en":"No. BellaBot can position itself by laser without markers. Markers are an alternative for venues with ceilings up to 8 m. We will advise which suits your venue.","th":"ไม่จำเป็น BellaBot ระบุตำแหน่งด้วยเลเซอร์ได้โดยไม่ต้องใช้มาร์กเกอร์ ส่วนมาร์กเกอร์เป็นอีกทางเลือกสำหรับสถานที่ที่เพดานสูงไม่เกิน 8 เมตร เราจะแนะนำวิธีที่เหมาะกับร้านของคุณ"}},{"question":{"en":"How much can it carry in one trip?","th":"ขนได้มากแค่ไหนต่อรอบ"},"answer":{"en":"Up to 40 kg across four trays, with up to 10 kg on each tray.","th":"ได้ถึง 40 กก. บน 4 ถาด ถาดละไม่เกิน 10 กก."}},{"question":{"en":"Can it go up a ramp?","th":"ขึ้นทางลาดได้หรือไม่"},"answer":{"en":"Yes, slopes of up to 5°. Steeper ramps and steps need another route.","th":"ได้ ทางลาดไม่เกิน 5° หากชันกว่านั้นหรือเป็นขั้นบันได ต้องใช้เส้นทางอื่น"}},{"question":{"en":"How long does the battery last?","th":"แบตเตอรี่ใช้งานได้นานเท่าไร"},"answer":{"en":"Up to 13 hours on a charge without a load, and 4.5 hours to recharge. The battery can be swapped for a charged one to keep it running.","th":"ใช้งานได้สูงสุด 13 ชั่วโมงต่อการชาร์จเมื่อไม่มีน้ำหนักบรรทุก และชาร์จเต็มใน 4.5 ชั่วโมง สามารถเปลี่ยนเป็นแบตเตอรี่ที่ชาร์จไว้แล้วเพื่อทำงานต่อได้ทันที"}}]}'::jsonb
where id = 'pudu-bella';

commit;

